                && !(status.isOpen() && !bound && person.retiredAsOf(asOf))
                && !((status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED) && !bound
                        && claim.getDeferredUntil() != null
                        && asOf.isBefore(claim.getDeferredUntil()));
